mapper.select:
select v.* , nvl((select max(( CASE hur.RELATION_DOCUMENT_ID WHEN NULL THEN 'N' ELSE 'Y' END )) from hls_user_relationship hur where v.chance_id = hur.RELATION_DOCUMENT_ID and hur.SOURCE_USER_ID = #{userId}),'N') collectFlag from( select nvl(p.project_status,'NEW') project_status, p.company_id, p.credit_amount, (select bp_name from hls_bp_master where bp_id=p.tenant_id) as bp_name, p.chance_id, p.employee_id, p.ref_project_id, p.tenant_id, p.project_number, p.project_name, p.project_assistant, p.CREATION_DATE, p.CREATED_BY, nvl(hd.description,p.division) division_desc, (select hdt.description from hls_document_type hdt where hdt.business_type=p.business_type and hdt.document_category=p.document_category and hdt.document_type=p.document_type) as document_type_desc, hds.description project_status_desc from prj_project p LEFT JOIN hls_division hd on p.division=hd.division and p.company_id = hd.company_id LEFT JOIN (select * from hls_document_status t1 where t1.document_category='PRJ_PROJECT') hds on hds.status_code=nvl(p.project_status,'NEW') ) v
1=1 and (v.created_by = #{request.userId} or EXISTS (select 1 from fnd_employee fe where fe.employee_id = v.project_assistant and fe.employee_code = #{request.employeeCode}) or 10001=#{request.userId} or EXISTS (select 1 from sys_user_authority_trx suat where suat.user_id=#{request.userId} and suat.document_category='PRJ_CHANCE' and suat.document_id=v.chance_id and suat.authority_source_type='Y'))
and v.company_id = #{companyId}
and v.project_status = #{projectStatus}
and ((v.project_number like concat(concat('%',#{params}),'%')) or (v.project_name like concat(concat('%',#{params}),'%')) or (v.bp_name like concat(concat('%',#{params}),'%')))
order by v.CREATION_DATE desc
